<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/helpers.php';require_once __DIR__.'/../includes/geop_v8.php';
geop_v8_boot($pdo);check_csrf();
$pending=$_SESSION['2fa_pending_user']??null;if(!$pending){if(is_logged_in())redirect('index');redirect('login');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$code=(string)($_POST['codigo']??'');$st=$pdo->prepare('SELECT * FROM usuarios WHERE id=? AND status=\'ATIVO\' LIMIT 1');$st->execute([(int)$pending['id']]);$u=$st->fetch(PDO::FETCH_ASSOC);if(!$u||empty($u['totp_enabled'])||empty($u['totp_secret_enc']))throw new RuntimeException('2FA não está disponível para esta conta.');$secret=geop_v8_decrypt((string)$u['totp_secret_enc']);if(!geop_v8_totp_verify($secret,$code))throw new RuntimeException('Código inválido.');unset($u['senha_hash'],$u['totp_secret_enc']);$_SESSION['user']=$u;$_SESSION['senha_troca_obrigatoria']=password_change_required($u)?1:0;$_SESSION['geop_last_activity']=time();unset($_SESSION['2fa_pending_user']);geop_v8_login_attempt($pdo,(string)$u['email'],(int)$u['id'],true,'2FA_OK');geop_v8_security_event($pdo,(int)$u['id'],'LOGIN_2FA_SUCESSO');if(!empty($_SESSION['senha_troca_obrigatoria']))redirect('mudar_senha?obrigatoria=1');redirect('index');}catch(Throwable $e){$error=$e->getMessage();geop_v8_security_event($pdo,(int)($pending['id']??0),'LOGIN_2FA_FALHA',$error);}
}
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verificação 2FA - GEOP</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?=e(app_path('assets/style.css'))?>"></head><body class="login-page"><div class="login-card card p-4"><div class="login-logo">PDU</div><h1 class="h4 text-center">Verificação em duas etapas</h1><p class="text-muted text-center">Digite o código do seu aplicativo autenticador.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Código</label><input class="form-control form-control-lg text-center mb-3" name="codigo" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="one-time-code" required autofocus><button class="btn btn-primary w-100">Validar</button></form><div class="text-center mt-3"><a href="<?=e(app_path('logout'))?>">Cancelar acesso</a></div></div></body></html>
